Name: buffer_fill
Signature: void buffer_fill(buffer_t *self, int c)
Description: /**
 * @brief Fill a buffer with a specified byte value.
 *
 * Sets all bytes in the buffer's data array to the given value, overwriting
 * any existing contents. The operation affects exactly self->len bytes.
 *
 * @param self Pointer to a buffer_t structure. Must not be NULL, and
 *             self->data must point to a valid memory region of at least
 *             self->len bytes.
 * @param c Byte value to set, interpreted as an unsigned char.
 *
 * @return None.
 *
 * @note The buffer's contents are replaced; other fields in self are not modified.
 */
Dependencies: None

