// Contains target function implementation and dependency signatures

#include <string.h>
#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <ctype.h>
#include <sys/types.h>
#include "buffer.h"

// Target function implementation
void
buffer_fill(buffer_t *self, int c) {
  memset(self->data, c, self->len);
}

